CREATE TRIGGER VehicleEvidenceIdentity_update BEFORE UPDATE ON Vehicle WHEN (NEW.VehicleModelId IS NOT OLD.VehicleModelId) AND EXISTS (SELECT 1 FROM VehicleActivity a WHERE a.VehicleId=OLD.Id AND (EXISTS (SELECT 1 FROM EventEvaluation WHERE VehicleActivityId=a.Id) OR EXISTS (SELECT 1 FROM EventEvaluationActivity WHERE VehicleActivityId=a.Id) OR EXISTS (SELECT 1 FROM PeriodEvaluationActivity WHERE VehicleActivityId=a.Id))) BEGIN SELECT RAISE(ABORT, 'Vehicle model used in final evidence is immutable'); END;
